import { Effect } from "effect"
import * as Toml from "smol-toml"

export interface ReleaseManifest {
  readonly package: string
  readonly version: string
  readonly channel: string
}

export const readManifest = (source: string) =>
  Effect.try({
    try: (): ReleaseManifest => {
      const document = Toml.parse(source)
      if (
        typeof document.package !== "string" ||
        typeof document.version !== "string" ||
        typeof document.channel !== "string"
      ) {
        throw new Error("Release manifest requires package, version, and channel")
      }
      return {
        package: document.package,
        version: document.version,
        channel: document.channel
      }
    },
    catch: (cause) => new Error("Unable to read release manifest", { cause })
  })

export const writeManifest = (manifest: ReleaseManifest): string =>
  Toml.stringify({
    package: manifest.package,
    version: manifest.version,
    channel: manifest.channel
  })
